/* correlation.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "correlation.h"


/* Array initialization. */
static
void init_array (int m,
		 int n,
		 DATA_TYPE *float_n,
		 DATA_TYPE POLYBENCH_2D(data,N,M,n,m))
{
  int i, j;

  *float_n = (DATA_TYPE)N;

  for (i = 0; i < N; i++)
    for (j = 0; j < M; j++)
      data[i][j] = (DATA_TYPE)(i*j)/M + i;

}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m,
		 DATA_TYPE POLYBENCH_2D(corr,M,M,m,m))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("corr");
  for (i = 0; i < m; i++)
    for (j = 0; j < m; j++) {
      if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, corr[i][j]);
    }
  POLYBENCH_DUMP_END("corr");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_correlation [[gnu::flatten, gnu::noinline]] (int m, int n,
			DATA_TYPE float_n,
			DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
			DATA_TYPE POLYBENCH_2D(corr,M,M,m,m),
			DATA_TYPE POLYBENCH_1D(mean,M,m),
			DATA_TYPE POLYBENCH_1D(stddev,M,m))
{
  int i, j, k;

  /* Epsilon to avoid division by (near) zero. */
  DATA_TYPE eps = SCALAR_VAL(0.1);

  /* Precompute sqrt(float_n) once; used later in normalization. */
  DATA_TYPE sqrt_float_n = SQRT_FUN(float_n);

  /* Precompute 1 / float_n to avoid repeated divisions in mean/stddev. */
  DATA_TYPE inv_float_n = SCALAR_VAL(1.0) / float_n;

#pragma scop

  /* --------------------------------------------------------------------
   * 1. Compute column means.
   *
   * Original code used:
   *   for (j) { mean[j] = 0; for (i) mean[j] += data[i][j]; mean[j]/=float_n; }
   *
   * We compute the same quantities but traverse the data row-wise to
   * improve spatial locality: each row is accessed contiguously.
   * For each column j, the sequence of additions over i is unchanged.
   * -------------------------------------------------------------------- */

  /* Initialize means. */
  for (j = 0; j < _PB_M; j++)
    mean[j] = SCALAR_VAL(0.0);

  /* Accumulate sums row by row. */
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE *data_row = data[i];
      for (j = 0; j < _PB_M; j++)
        mean[j] += data_row[j];
    }

  /* Divide by float_n (same as original, just factored into a separate loop). */
  for (j = 0; j < _PB_M; j++)
    mean[j] *= inv_float_n;


  /* --------------------------------------------------------------------
   * 2. Compute column standard deviations.
   *
   * Original code, per column j:
   *   stddev[j] = 0;
   *   for (i) stddev[j] += (data[i][j] - mean[j])^2;
   *   stddev[j] /= float_n;
   *   stddev[j] = sqrt(stddev[j]);
   *   if (stddev[j] <= eps) stddev[j] = 1.0;
   *
   * We again traverse the data row-wise for better cache behavior. The
   * order of operations for each stddev[j] (adds over i, then division,
   * sqrt, threshold) remains mathematically identical.
   *
   * Additionally, we transform stddev[] to store, after this phase, the
   * *normalization factor*:
   *
   *   stddev[j] <- 1 / (sqrt(float_n) * original_stddev[j])
   *
   * This lets us replace a divide in the normalization loop by a
   * cheaper multiply while preserving the mathematical result.
   * -------------------------------------------------------------------- */

  /* Initialize variance accumulators. */
  for (j = 0; j < _PB_M; j++)
    stddev[j] = SCALAR_VAL(0.0);

  /* Accumulate squared differences row by row. */
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE *data_row = data[i];
      for (j = 0; j < _PB_M; j++)
        {
          DATA_TYPE diff = data_row[j] - mean[j];
          stddev[j] += diff * diff;
        }
    }

  /* Finalize stddev and convert to normalization factors. */
  for (j = 0; j < _PB_M; j++)
    {
      /* Compute variance and standard deviation. */
      DATA_TYPE var = stddev[j] * inv_float_n;
      DATA_TYPE std = SQRT_FUN(var);

      /* Handle near-zero standard deviation as in original code. */
      std = (std <= eps) ? SCALAR_VAL(1.0) : std;

      /* Store 1 / (sqrt(float_n) * stddev_original[j]) into stddev[j].
       * Later, normalized values will be:
       *   (data[i][j] - mean[j]) * stddev[j]
       * which is equivalent to original:
       *   (data[i][j] - mean[j]) / (sqrt(float_n) * stddev_original[j])
       */
      stddev[j] = SCALAR_VAL(1.0) / (sqrt_float_n * std);
    }


  /* --------------------------------------------------------------------
   * 3. Center and reduce the column vectors (normalize data in-place).
   *
   * Original code:
   *   data[i][j] -= mean[j];
   *   data[i][j] /= sqrt(float_n) * stddev[j];
   *
   * Now stddev[j] already holds 1/(sqrt(float_n)*original_stddev[j]),
   * so we can do a single multiply. Access pattern is row-wise for
   * better cache locality.
   * -------------------------------------------------------------------- */

  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE *data_row = data[i];
      for (j = 0; j < _PB_M; j++)
        {
          data_row[j] = (data_row[j] - mean[j]) * stddev[j];
        }
    }


  /* --------------------------------------------------------------------
   * 4. Calculate the m * m correlation matrix.
   *
   * The correlation matrix for normalized data is:
   *   corr[i][j] = sum_k data[k][i] * data[k][j]
   *
   * The original code:
   *   for (i = 0; i < M-1; i++) {
   *     corr[i][i] = 1.0;
   *     for (j = i+1; j < M; j++) {
   *       corr[i][j] = 0.0;
   *       for (k = 0; k < N; k++)
   *         corr[i][j] += data[k][i] * data[k][j];
   *       corr[j][i] = corr[i][j];
   *     }
   *   }
   *   corr[M-1][M-1] = 1.0;
   *
   * We keep the same mathematical computation, but:
   *   - Accumulate into a local scalar 'sum' to reduce memory traffic.
   *   - Initialize the diagonal in a separate loop.
   *   - Parallelize the outer loop over i using OpenMP; each (i,j) pair
   *     is computed by exactly one thread, so there are no data races.
   *   - For each (i,j), the inner loop over k still runs in ascending
   *     order, preserving the reduction order for that pair.
   * -------------------------------------------------------------------- */

  /* Set diagonal elements to 1.0. */
  for (i = 0; i < _PB_M; i++)
    corr[i][i] = SCALAR_VAL(1.0);

  /* Compute upper triangle and mirror to lower triangle. */
  #pragma omp parallel for private(j,k) schedule(static)
  for (i = 0; i < _PB_M - 1; i++)
    {
      for (j = i + 1; j < _PB_M; j++)
        {
          DATA_TYPE sum = SCALAR_VAL(0.0);

          /* Dot product of column i and column j. */
          for (k = 0; k < _PB_N; k++)
            {
              sum += data[k][i] * data[k][j];
            }

          corr[i][j] = sum;
          corr[j][i] = sum;
        }
    }

#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE float_n;
  POLYBENCH_2D_ARRAY_DECL(data,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(corr,DATA_TYPE,M,M,m,m);
  POLYBENCH_1D_ARRAY_DECL(mean,DATA_TYPE,M,m);
  POLYBENCH_1D_ARRAY_DECL(stddev,DATA_TYPE,M,m);

  /* Initialize array(s). */
  init_array (m, n, &float_n, POLYBENCH_ARRAY(data));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_correlation (m, n, float_n,
		      POLYBENCH_ARRAY(data),
		      POLYBENCH_ARRAY(corr),
		      POLYBENCH_ARRAY(mean),
		      POLYBENCH_ARRAY(stddev));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, POLYBENCH_ARRAY(corr)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(data);
  POLYBENCH_FREE_ARRAY(corr);
  POLYBENCH_FREE_ARRAY(mean);
  POLYBENCH_FREE_ARRAY(stddev);

  return 0;
}
