      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, corr[i][j]);
    }
  POLYBENCH_DUMP_END("corr");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied (while preserving original semantics):
   - Use restrict-qualified local aliases for the main arrays to help
     the compiler vectorize and avoid pessimistic aliasing assumptions.
   - Hoist and reuse expensive operations:
       * Replace divisions by float_n with a single precomputed reciprocal.
       * Replace per-element division by (sqrt(float_n) * stddev[j])
         with a precomputed per-column scale factor 1 / (sqrt(float_n)*stddev[j]).
       * Compute sqrt(float_n) only once.
   - Improve computational intensity of the normalization step by
     turning divides into multiplies.
   - Add OpenMP pragmas to exploit available parallelism across
     columns and across rows, without changing the numerical algorithm.
*/
static
void kernel_correlation[[gnu::flatten, gnu::noinline]](int m, int n,
			DATA_TYPE float_n,
			DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
			DATA_TYPE POLYBENCH_2D(corr,M,M,m,m),
			DATA_TYPE POLYBENCH_1D(mean,M,m),
			DATA_TYPE POLYBENCH_1D(stddev,M,m))
{
  int i, j, k;

  const DATA_TYPE eps = SCALAR_VAL(0.1);

  /* Create local restrict-qualified aliases.  In this benchmark the
     arrays data, corr, mean and stddev are all distinct, so it is
     safe to promise non-aliasing to the compiler, which improves
     vectorization and memory scheduling. */
  DATA_TYPE (* __restrict data_)[m]  = data;
  DATA_TYPE (* __restrict corr_)[m]  = corr;
  DATA_TYPE * __restrict mean_       = mean;
  DATA_TYPE * __restrict stddev_     = stddev;

  /* Reciprocal of float_n is reused several times. */
  const DATA_TYPE float_n_inv = SCALAR_VAL(1.0) / float_n;

#pragma scop
  /* 1. Compute mean of each column:
         mean[j] = (1/float_n) * sum_i data[i][j].
     Outer loop is parallelized across columns; each thread works on
     independent j, so no synchronization is needed inside. */
#pragma omp parallel for private(i) schedule(static)
  for (j = 0; j < _PB_M; j++)
    {
      DATA_TYPE mean_j = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_N; i++)
        mean_j += data_[i][j];
      mean_[j] = mean_j * float_n_inv;
    }

  /* 2. Compute standard deviation of each column:
         stddev[j] = sqrt( (1/float_n) * sum_i (data[i][j] - mean[j])^2 ).
     We keep exactly the same formula as the original code, including
     the near-zero handling, but avoid redundant loads of mean[j]. */
#pragma omp parallel for private(i) schedule(static)
  for (j = 0; j < _PB_M; j++)
    {
      DATA_TYPE mean_j   = mean_[j];
      DATA_TYPE stddev_j = SCALAR_VAL(0.0);

      for (i = 0; i < _PB_N; i++)
        {
          DATA_TYPE diff = data_[i][j] - mean_j;
          stddev_j += diff * diff;
        }

      stddev_j *= float_n_inv;
      stddev_j  = SQRT_FUN(stddev_j);

      /* Handle near-zero std. dev. to avoid later division by zero. */
      if (stddev_j <= eps)
        stddev_j = SCALAR_VAL(1.0);

      stddev_[j] = stddev_j;
    }

  /* 3. Precompute scaling factors:
         scale[j] = 1 / (sqrt(float_n) * stddev[j]).
     We overwrite stddev[] with these scale factors because the
     original stddev values are not used after normalization.
     This turns a costly per-element division into a much cheaper
     multiplication, and computes sqrt(float_n) only once. */
  const DATA_TYPE inv_sqrt_float_n = SCALAR_VAL(1.0) / SQRT_FUN(float_n);
  for (j = 0; j < _PB_M; j++)
    stddev_[j] = inv_sqrt_float_n / stddev_[j];

  /* 4. Center and reduce the column vectors in-place:
         data[i][j] = (data[i][j] - mean[j]) * scale[j].
     This is equivalent to the original
         (data[i][j] - mean[j]) / (sqrt(float_n) * stddev[j])
     but performed as a multiply with a precomputed scale factor.
     The nested loops are parallelized over (i,j) with collapse(2)
     to expose 2D parallelism. */
#pragma omp parallel for collapse(2) schedule(static)
  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_M; j++)
      {
        DATA_TYPE diff = data_[i][j] - mean_[j];
        data_[i][j] = diff * stddev_[j];
      }

  /* 5. Compute the m x m correlation matrix.
     After step 4, each column has been centered and scaled, so the
     correlation between columns i and j is simply the dot product of
     these normalized columns:
         corr[i][j] = sum_k data[k][i] * data[k][j].
     The matrix is symmetric; we compute only the upper triangular
     part (including diagonal except the last one) and mirror it. */
#pragma omp parallel for private(j,k) schedule(static)
  for (i = 0; i < _PB_M-1; i++)
    {
      corr_[i][i] = SCALAR_VAL(1.0);

      for (j = i+1; j < _PB_M; j++)
        {
          DATA_TYPE corr_ij = SCALAR_VAL(0.0);

          /* Inner dot-product; with the restrict-qualified aliases
             above, compilers can safely vectorize this loop. */
          for (k = 0; k < _PB_N; k++)
            corr_ij += data_[k][i] * data_[k][j];

          corr_[i][j] = corr_ij;
          corr_[j][i] = corr_ij;
        }
    }

  /* Last diagonal element. */
  corr_[_PB_M-1][_PB_M-1] = SCALAR_VAL(1.0);
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE float_n;
  POLYBENCH_2D_ARRAY_DECL(data,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(corr,DATA_TYPE,M,M,m,m);
  POLYBENCH_1D_ARRAY_DECL(mean,DATA_TYPE,M,m);
  POLYBENCH_1D_ARRAY_DECL(stddev,DATA_TYPE,M,m);

