/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Reordered loops for mean/stddev computation to iterate over
     rows in the outer loop and columns in the inner loop, which
     matches the row-major layout of `data` and improves cache
     locality.
   - Used per-thread temporary arrays and OpenMP parallel regions
     to compute mean and stddev with reduced contention and good
     memory locality.
   - Precomputed 1/N and sqrt(N) once and reused.
   - Replaced repeated divisions during normalization with a single
     precomputed scaling factor per column and a multiplication.
   - Parallelized the normalization over rows.
   - Parallelized the correlation computation over the outer
     column index and added a SIMD hint on the innermost loop.
   - Used pointer increment form in the innermost correlation loop
     to avoid repeated index arithmetic and help vectorization.

   All transformations preserve the mathematical definition of the
   correlation matrix; only the order of floating‑point additions
   is changed.
*/
static
void kernel_correlation[[gnu::flatten, gnu::noinline]](int m, int n,
			DATA_TYPE float_n,
			DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
			DATA_TYPE POLYBENCH_2D(corr,M,M,m,m),
			DATA_TYPE POLYBENCH_1D(mean,M,m),
			DATA_TYPE POLYBENCH_1D(stddev,M,m))
{
  int i, j, k;

  const DATA_TYPE eps = SCALAR_VAL(0.1);

#pragma scop

  /* --------------------------------------------------------------------
   * 1. Compute column means
   * ------------------------------------------------------------------*/

  /* Initialize means to zero. */
  for (j = 0; j < _PB_M; j++)
    mean[j] = SCALAR_VAL(0.0);

  /* Parallel reduction over rows with per-thread partial sums.
     Inner loop runs over columns to exploit row-major layout. */
#pragma omp parallel
  {
    DATA_TYPE mean_local[_PB_M];

    for (j = 0; j < _PB_M; j++)
      mean_local[j] = SCALAR_VAL(0.0);

#pragma omp for nowait
    for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE * __restrict data_row = data[i];
      for (j = 0; j < _PB_M; j++)
        mean_local[j] += data_row[j];
    }

    /* Merge per-thread partial sums into the global mean. */
#pragma omp critical
    {
      for (j = 0; j < _PB_M; j++)
        mean[j] += mean_local[j];
    }
  }

  /* Divide by N to finalize means. */
  const DATA_TYPE inv_float_n = SCALAR_VAL(1.0) / float_n;
  for (j = 0; j < _PB_M; j++)
    mean[j] *= inv_float_n;


  /* --------------------------------------------------------------------
   * 2. Compute column standard deviations
   * ------------------------------------------------------------------*/

  /* Initialize stddev accumulators to zero. */
  for (j = 0; j < _PB_M; j++)
    stddev[j] = SCALAR_VAL(0.0);

  /* Parallel reduction over rows for variance (sum of squared
     differences from the mean). */
#pragma omp parallel
  {
    DATA_TYPE stddev_local[_PB_M];

    for (j = 0; j < _PB_M; j++)
      stddev_local[j] = SCALAR_VAL(0.0);

#pragma omp for nowait
    for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE * __restrict data_row = data[i];
      for (j = 0; j < _PB_M; j++)
      {
        DATA_TYPE diff = data_row[j] - mean[j];
        stddev_local[j] += diff * diff;
      }
    }

    /* Merge per-thread partial sums into the global stddev. */
#pragma omp critical
    {
      for (j = 0; j < _PB_M; j++)
        stddev[j] += stddev_local[j];
    }
  }

  /* Finalize stddev: divide by N, take sqrt, and clamp small values. */
  for (j = 0; j < _PB_M; j++)
  {
    stddev[j] *= inv_float_n;
    stddev[j] = SQRT_FUN(stddev[j]);
    /* Handle near-zero std. dev. values to avoid divide-by-zero later. */
    stddev[j] = (stddev[j] <= eps) ? SCALAR_VAL(1.0) : stddev[j];
  }


  /* --------------------------------------------------------------------
   * 3. Center and reduce the column vectors
   * ------------------------------------------------------------------*/

  /* Precompute 1 / (sqrt(N) * stddev[j]) scaling factors to replace
     per-element divisions with cheaper multiplications. */
  const DATA_TYPE sqrt_float_n = SQRT_FUN(float_n);
  DATA_TYPE col_scale[_PB_M];

  for (j = 0; j < _PB_M; j++)
    col_scale[j] = SCALAR_VAL(1.0) / (sqrt_float_n * stddev[j]);

  /* Normalize data: (data[i][j] - mean[j]) / (sqrt(N) * stddev[j]).
     Loop order (rows outer, columns inner) matches row-major storage. */
#pragma omp parallel for private(j) schedule(static)
  for (i = 0; i < _PB_N; i++)
  {
    DATA_TYPE * __restrict data_row = data[i];
    for (j = 0; j < _PB_M; j++)
    {
      data_row[j] = (data_row[j] - mean[j]) * col_scale[j];
    }
  }


  /* --------------------------------------------------------------------
   * 4. Calculate the m * m correlation matrix
   * ------------------------------------------------------------------*/

  /* For each pair of columns (i, j) with i < j, compute the dot product
     of the normalized columns. The outer loop over i is parallelized.
     Each (i, j) pair is independent, and we write to disjoint elements
     of `corr`, so no synchronization is required inside the loop. */
#pragma omp parallel for private(j, k) schedule(static)
  for (i = 0; i < _PB_M - 1; i++)
  {
    corr[i][i] = SCALAR_VAL(1.0);

    for (j = i + 1; j < _PB_M; j++)
    {
      DATA_TYPE sum = SCALAR_VAL(0.0);

      /* Pointers that walk down columns i and j with stride _PB_M.
         This avoids repeated index arithmetic inside the innermost loop. */
      DATA_TYPE *pi = &data[0][i];
      DATA_TYPE *pj = &data[0][j];

#pragma omp simd reduction(+:sum)
      for (k = 0; k < _PB_N; k++)
      {
        sum += (*pi) * (*pj);
        pi += _PB_M;
        pj += _PB_M;
      }

      corr[i][j] = sum;
      corr[j][i] = sum;
    }
  }

  /* Last diagonal element. */
  corr[_PB_M-1][_PB_M-1] = SCALAR_VAL(1.0);

#pragma endscop
}


