    /* Step 2: compute standard deviations.                               */
    /*                                                                     */
    /* Original:                                                          */
    /*   stddev[j] = sqrt( (1/float_n) * sum_i (data[i][j]-mean[j])^2 );  */
    /*   if (stddev[j] <= eps) stddev[j] = 1.0;                           */
