    /*                                                                     */
    /* Original:                                                          */
    /*   for (i)                                                          */
    /*     for (j) {                                                      */
    /*       data[i][j] -= mean[j];                                       */
    /*       data[i][j] /= sqrt(float_n) * stddev[j];                     */
    /*     }                                                              */
    /*                                                                     */
    /* Our version uses the precomputed inverse scaling factors in        */
    /* stddev_r[] and iterates in row-major order for better locality:    */
    /*   data[i][j] = (data[i][j] - mean[j]) * stddev_r[j];               */
    /* ------------------------------------------------------------------ */
#pragma omp for schedule(static)
    for (i = 0; i < _PB_N; i++)
    {
      for (j = 0; j < _PB_M; j++)
      {
        DATA_TYPE centered = data_r[i][j] - mean_r[j];
        data_r[i][j] = centered * stddev_r[j];
      }
    }

    /* ------------------------------------------------------------------ */
    /* Step 4: compute the m x m correlation matrix.                      */
    /*                                                                     */
    /* corr[i][j] = sum_k data[k][i] * data[k][j] for i < j               */
    /* corr is symmetric, and diag(corr) is set to 1.0 explicitly.        */
